let loading;
export function loadMaps(){if(globalThis.L)return Promise.resolve(globalThis.L);if(loading)return loading;loading=new Promise((resolve,reject)=>{if(!document.querySelector('[data-borali-map-style]')){const style=document.createElement('link');style.rel='stylesheet';style.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';style.dataset.boraliMapStyle='';document.head.append(style);}const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';const fail=()=>{clearTimeout(timer);script.onload=null;script.onerror=null;script.remove();loading=null;reject(new Error('Mapa indisponível. Tente retomar a sessão.'));};const timer=setTimeout(fail,12000);script.onload=()=>{clearTimeout(timer);resolve(globalThis.L);};script.onerror=fail;document.head.append(script);});return loading;}
